/*
 * no_output_module - for a box used as an analyser rather than as a processor.
 *
 * The ADC still runs, the effects still run, and the spectrum still shows what
 * the active effect is putting out. What leaves the DAC is silence.
 *
 * ---- what this cannot do, and why ---------------------------------------
 *
 * **It does not turn the DAC off, and it cannot.** MCLK, BCK and LRCK are
 * generated by the one PIO state machine that also carries both data
 * directions, and the PCM1808 is a slave with no internal PLL - it needs those
 * clocks or it produces nothing. Stopping the output stage would stop the
 * input with it.
 *
 * So the pins keep toggling and the DMA ring keeps running; what changes is
 * that the samples reaching them are zero. The DAC sits at its idle level and
 * whatever is downstream hears nothing. If the goal is to save power or free
 * the pins, this is not the lever - that is a different i2s.pio and a different
 * audio.c, and it would have to give up the ADC or clock it from somewhere
 * else.
 *
 * ---- where this sits in the block, and why it matters -------------------
 *
 * write() is called **after** spectrum_feed(), which is the whole point: the
 * analyser sees the effect's real output and the DAC does not. Zeroing any
 * earlier would blank the display too, and the display is the reason this
 * module exists.
 *
 * ---- it still claims the pin ---------------------------------------------
 *
 * attach() calls audio_claim_dout() exactly as i2s_output_module does, and
 * that is deliberate rather than copy-paste. Leaving GP16 unclaimed would
 * genuinely stop data reaching the DAC - it is the one thing this module
 * *could* do that it cannot do any other way - and it would do it by leaving
 * the PCM5102A's DIN floating against a running BCK and LRCK. A CMOS input
 * left floating is worse than one being fed zeroes, and the audible result is
 * the same silence either way. So the pin is driven and the samples are zero.
 *
 * ---- the cost ------------------------------------------------------------
 *
 * The zeroing is a memset over the block the effect just wrote, so it costs a
 * few hundred cycles and nothing else - it does not make the effect cheaper.
 * An effect still runs at its full cost with this module selected, which is
 * worth knowing if the reason for choosing it was headroom rather than silence.
 */

#include "module.h"
#include "audio.h"

#include <string.h>

static void none_attach(void)
{
    // See "it still claims the pin" above: driven and silent, not floating.
    audio_claim_dout();
}

static void none_write(int32_t *buf)
{
    memset(buf, 0, AUDIO_BLOCK_SAMPLES * sizeof *buf);
}

static void none_report(void)
{
    NOVA_LOG("  output: none - DAC fed silence; clocks still run for the ADC\n");
}

static const output_module_t kModule = {
    .name   = "none",
    .init   = NULL,
    .attach = none_attach,
    .write  = none_write,
    .report = none_report,
};

const output_module_t *no_output_module(void) { return &kModule; }
